 await seek(Math.min(reference.duration-.001,baseTime),controller.signal);frame=document.createElement('canvas');frame.width=video.videoWidth;frame.height=video.videoHeight;frame.getContext('2d').drawImage(video,0,0);if(['dissolve','wipe'].includes(item.preview.kind)){await seek(item.end,controller.signal);secondFrame=document.createElement('canvas');secondFrame.width=video.videoWidth;secondFrame.height=video.videoHeight;secondFrame.getContext('2d').drawImage(video,0,0)}await seek(begin,controller.signal);
 const isText=item.preview.kind==='text';$('compare-label').textContent=isText?'字幕几何复现 · 中性背景（字体样式未还原）':`${secondFrame?'前后两幅参考帧':'固定参考帧 '+baseTime.toFixed(3)+' 秒'} + 参数复现示意`;
 const draw=()=>{const time=video.currentTime,state=comparisonState(item,time);ctx.fillStyle=isText?'#172033':'#000';ctx.fillRect(0,0,640,360);if(state?.kind==='text'){if(state.visible){ctx.font='bold 48px sans-serif';const width=ctx.measureText(state.text).width,scale=state.width*640/Math.max(1,width);ctx.save();ctx.translate(state.x*640,state.y*360);ctx.scale(scale,scale);ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#fff';ctx.fillText(state.text,0,0);ctx.restore()}}else{ctx.save();ctx.globalAlpha=['dissolve','wipe'].includes(state?.kind)?1:state?.alpha??1;if(state?.kind==='rotation'){ctx.translate(320,180);ctx.rotate(state.angle*Math.PI/180);ctx.translate(-320,-180)}if(state?.kind==='pan'){const ratio=Math.min(640/frame.width,360/frame.height);ctx.translate(state.x*frame.width*ratio,state.y*frame.height*ratio);}fit(frame,state?.scale??1);ctx.restore();if(state?.kind==='dissolve'&&secondFrame){ctx.save();ctx.globalAlpha=state.alpha;fit(secondFrame);ctx.restore()}if(state?.kind==='wipe'&&secondFrame){const ratio=Math.min(640/frame.width,360/frame.height),w=frame.width*ratio,h=frame.height*ratio,x=(640-w)/2,y=(360-h)/2,p=Math.max(0,Math.min(1,state.progress));ctx.save();ctx.beginPath();ctx.rect(x+(state.axis==='x'&&!state.fromStart?w*(1-p):0),y+(state.axis==='y'&&!state.fromStart?h*(1-p):0),state.axis==='x'?w*p:w,state.axis==='y'?h*p:h);ctx.clip();fit(secondFrame);ctx.restore()}if(state?.white||state?.black||state?.color){ctx.fillStyle=state.color||(state.black?'#000':'#fff');const ratio=Math.min(640/frame.width,360/frame.height);ctx.fillRect((640-frame.width*ratio)/2,(360-frame.height*ratio)/2,frame.width*ratio,frame.height*ratio)}}$('compare-clock').textContent=time.toFixed(3)+' 秒';$('compare-time').value=String(Math.max(0,Math.min(1,(time-begin)/(end-begin))))};
